import { globalOptionsTrailer, helpWidth, wrapHelpText } from "./utils/help_text.js";
import { consumeBlockIfMatches, consumeNextMatching, drawPointer, splitColumns } from "./utils/ui.js";
import chalk from "chalk";
import cliui from "cliui";
//#region src/help.ts
const SPACE_WIDTH = 20;
const DESCRIPTION_GUTTER = 4;
const wrapDescription = (text) => wrapHelpText(text, Math.max(1, helpWidth() - SPACE_WIDTH - DESCRIPTION_GUTTER));
const isGlobalOptionsHeader = (header) => /global options:/i.test(header);
const isTopLevelUsage = (usage) => /^\S+ <command>/.test(usage);
const renderOptionBlock = (optionsBlock) => {
	const result = [];
	const [header, ...body] = optionsBlock;
	if (header === void 0) return result;
	result.push(header);
	body.forEach((line) => {
		const [option, description] = splitColumns(line);
		const ui = cliui({
			width: helpWidth(),
			wrap: false
		});
		if (option.startsWith("-")) {
			ui.div({
				text: chalk.green(option),
				padding: [
					0,
					0,
					0,
					0
				]
			});
			ui.div({
				text: chalk.gray(drawPointer(SPACE_WIDTH)),
				width: SPACE_WIDTH,
				padding: [
					0,
					2,
					0,
					0
				]
			}, {
				text: chalk.rgb(210, 210, 210)(wrapDescription(description ?? "")),
				padding: [
					0,
					0,
					0,
					0
				]
			});
		} else ui.div({
			padding: [
				0,
				0,
				0,
				0
			],
			text: "",
			width: SPACE_WIDTH
		}, {
			text: chalk.rgb(210, 210, 210)(wrapDescription(option)),
			padding: [
				0,
				0,
				0,
				0
			]
		});
		result.push(ui.toString());
	});
	result.push("");
	return result;
};
const formatHelp = (help) => {
	const lines = help.split("\n");
	const result = [];
	const topLevelCommand = consumeNextMatching(lines, /^.*/);
	if (topLevelCommand) {
		result.push(chalk.bold(topLevelCommand.replace("[options]", chalk.reset.green("[options]"))));
		result.push("");
	}
	const consumeCommands = () => {
		const commandsBlock = consumeBlockIfMatches(lines, /^Commands:/);
		if (commandsBlock.length === 0) return;
		const header = commandsBlock.shift();
		if (header === void 0) return;
		result.push(header);
		const ui = cliui({
			width: helpWidth(),
			wrap: false
		});
		commandsBlock.forEach((line) => {
			if (/^\s{3,}/.exec(line)) {
				ui.div({
					text: "",
					width: SPACE_WIDTH,
					padding: [
						0,
						0,
						0,
						0
					]
				}, {
					text: wrapDescription(line.trim()),
					padding: [
						0,
						0,
						0,
						0
					]
				});
				return;
			}
			const [command, description] = splitColumns(line);
			if (!description && ui.rows.length > 1) {
				ui.rows[ui.rows.length - 2][0].text += command;
				return;
			}
			ui.div(chalk.cyan(command));
			ui.div({
				text: chalk.gray(drawPointer(SPACE_WIDTH)),
				width: SPACE_WIDTH,
				padding: [
					0,
					0,
					0,
					0
				]
			}, {
				text: wrapDescription(description),
				padding: [
					0,
					0,
					0,
					2
				]
			});
		});
		result.push(ui.toString());
		result.push("");
	};
	const consumePositionals = () => {
		const positionalsBlock = consumeBlockIfMatches(lines, /Positionals:/);
		if (positionalsBlock.length === 0) return;
		const header = positionalsBlock.shift();
		if (header === void 0) return;
		result.push(header);
		const ui = cliui({
			width: helpWidth(),
			wrap: false
		});
		positionalsBlock.forEach((line) => {
			const [positional, description] = splitColumns(line);
			ui.div({
				text: positional,
				width: SPACE_WIDTH,
				padding: [
					0,
					2,
					0,
					0
				]
			}, {
				text: wrapDescription(description),
				padding: [
					0,
					0,
					0,
					0
				]
			});
		});
		result.push(ui.toString());
		result.push("");
	};
	consumeCommands();
	consumePositionals();
	const descriptionBlock = consumeBlockIfMatches(lines, /^(?!.*options:)/i);
	if (descriptionBlock.length > 0) {
		result.push(...descriptionBlock);
		result.push("");
	}
	consumeCommands();
	consumePositionals();
	const optionBlocks = [];
	while (true) {
		const optionsBlock = consumeBlockIfMatches(lines, /.*options:/i);
		if (optionsBlock.length === 0) break;
		optionBlocks.push(optionsBlock);
	}
	for (const block of optionBlocks) {
		const header = block[0];
		if (header !== void 0 && !isGlobalOptionsHeader(header)) result.push(...renderOptionBlock(block));
	}
	const globalBlocks = optionBlocks.filter((block) => {
		const header = block[0];
		return header !== void 0 && isGlobalOptionsHeader(header);
	});
	if (topLevelCommand !== null && isTopLevelUsage(topLevelCommand)) for (const block of globalBlocks) result.push(...renderOptionBlock(block));
	else if (globalBlocks.length > 0 && topLevelCommand !== null) {
		result.push(globalOptionsTrailer(topLevelCommand));
		result.push("");
	}
	const exampleBlock = consumeBlockIfMatches(lines, /Examples:/);
	if (exampleBlock.length > 0) {
		result.push(exampleBlock.shift());
		const ui = cliui({
			width: helpWidth(),
			wrap: false
		});
		for (const line of exampleBlock) {
			const [command, description] = splitColumns(line);
			ui.div({
				text: chalk.bold(command),
				padding: [
					0,
					0,
					0,
					0
				]
			});
			ui.div({
				text: chalk.reset(wrapDescription(description)),
				padding: [
					0,
					0,
					0,
					2
				]
			});
		}
		result.push(ui.toString());
	}
	return [...result, ...lines];
};
const showHelp = async (argv) => {
	const help = await argv.getHelp();
	const text = `${formatHelp(help).join("\n")}\n`;
	await new Promise((resolve, reject) => {
		process.stdout.write(text, (err) => {
			if (err) {
				reject(err);
				return;
			}
			resolve();
		});
	});
	process.exit(0);
};
//#endregion
export { showHelp };
